from html import escape

def render_home(lang,pages,data,tx,link,button,event,resource,areas):
 t=lambda a,b:tx(lang,a,b)
 def url(key):return '/'+lang+'/'+pages[key]['slug'][lang].strip('/')+'/'
 icons=['<path d="M4 10 16 4l12 6M6 12h20M8 12v13m8-13v13m8-13v13M4 28h24"/>','<path d="M7 5h13l5 5v17H7zM20 5v6h5M11 16h10m-10 5h7"/>','<path d="m3 12 13-7 13 7-13 7zM8 16v8c5 4 11 4 16 0v-8m5-4v12"/>','<circle cx="16" cy="9" r="4"/><path d="M8 27v-5a8 8 0 0 1 16 0v5M3 24v-4a6 6 0 0 1 4-6m22 10v-4a6 6 0 0 0-4-6"/>']
 descriptions=[t('Contribuição técnica para o debate legislativo e as políticas públicas.','Technical contributions to legislative debate and public policy.'),t('Pesquisa e organização de evidências sobre segurança digital.','Research and evidence on digital security.'),t('Conhecimento para compreender riscos, responsabilidades e decisões.','Knowledge to understand risks, responsibilities and decisions.'),t('Diálogo entre instituições, pesquisadores e diferentes setores.','Dialogue between institutions, researchers and sectors.')]
 cards=''
 for i,key in enumerate(['policy','research','education','cooperation']):
  cards+=f'<a class="practice-card" href="{url(key)}"><div class="practice-top"><svg viewBox="0 0 32 32" aria-hidden="true">{icons[i]}</svg><span>0{i+1}</span></div><h3>{escape(pages[key][lang]["title"])}</h3><p>{descriptions[i]}</p><span class="card-action">{t("Saiba mais","Learn more")} <span aria-hidden="true">↗</span></span></a>'
 rsa=next(x for x in data['events'] if 'rsa' in x['id'])
 notice=next(x for x in data['events'] if x.get('featured'))
 carousel_data=data['carousel']
 slides=''
 for i,item in enumerate(carousel_data['slides']):
  slides+=f'<figure class="carousel-slide {"portrait-slide" if item["height"]>item["width"] else ""}" data-slide role="group" aria-roledescription="{t("slide","slide")}" aria-label="{i+1} {t("de","of")} {len(carousel_data["slides"])}" {"hidden" if i else ""}><div class="carousel-image"><img src="{escape(item["image"])}" width="{item["width"]}" height="{item["height"]}" alt="{escape(item["alt"][lang])}" {"fetchpriority=high" if i==0 else "loading=lazy"}></div><figcaption><strong>{escape(item["title"][lang])}</strong><p>{escape(item["description"][lang])}</p></figcaption></figure>'
 dots=''.join(f'<button type="button" class="carousel-dot" data-slide-to="{i}" aria-label="{t("Mostrar foto","Show photo")} {i+1}: {escape(item["title"][lang])}" aria-pressed="{str(i==0).lower()}"><span></span></button>' for i,item in enumerate(carousel_data['slides']))
 carousel=f'<section class="masthead-media photo-carousel" data-carousel data-interval="{carousel_data["intervalMs"]}" role="region" aria-roledescription="{t("carrossel","carousel")}" aria-label="{t("Fotos institucionais","Institutional photographs")}"><div class="carousel-viewport" aria-live="off">{slides}</div><div class="carousel-controls" hidden><button type="button" class="carousel-toggle" data-carousel-toggle aria-label="{t("Pausar carrossel","Pause carousel")}"><span data-rotation-icon aria-hidden="true">Ⅱ</span><span data-rotation-label>{t("Pausar","Pause")}</span></button><span class="carousel-counter" aria-hidden="true">01 / {len(carousel_data["slides"]):02d}</span><div class="carousel-arrows"><button type="button" data-carousel-prev aria-label="{t("Foto anterior","Previous photo")}">←</button><button type="button" data-carousel-next aria-label="{t("Próxima foto","Next photo")}">→</button></div></div><div class="carousel-timing" hidden><span data-timing-label>{t("Troca automática a cada 6 segundos","Automatic change every 6 seconds")}</span><div class="carousel-progress" aria-hidden="true"><span></span></div></div></section>'
 return f'''<main id="main" class="home-redesign">
 <section class="masthead"><div class="wrap masthead-grid"><div class="masthead-copy"><div class="masthead-title"><p class="eyebrow">{t('Instituto Brasileiro de Defesa Cibernética','Instituto Brasileiro de Defesa Cibernética')}</p><h1>{t('Cibersegurança<br>na agenda <em>pública.</em>','Cybersecurity<br>on the <em>public agenda.</em>')}</h1></div><div class="masthead-summary"><p class="masthead-intro">{t('Estudos, formação e diálogo institucional para contribuir com as políticas públicas de cibersegurança.','Research, education and institutional dialogue to contribute to cybersecurity policy.')}</p><div class="buttons">{button('institute',lang,t('Conheça o IBDCyber','Meet IBDCyber'))}{link('work',lang,t('Áreas de atuação','Our areas of work'))}</div><div class="hero-signature"><span></span>{t('Organização apartidária e sem fins lucrativos','A nonpartisan nonprofit organisation')}</div></div></div>{carousel}</div></section>
 <section class="spotlight-bar" aria-label="{t('Comunicado institucional','Institutional announcement')}"><div class="wrap spotlight-grid"><span class="spotlight-label"><span aria-hidden="true"></span>{t('Comunicado','Announcement')}</span><div><span class="mini-label">IBDCyber</span><h2>{escape(notice['title'][lang])}</h2></div><p>{escape(notice['summary'][lang])}</p><a class="text-link" href="{url('agenda')}{notice['id']}/">{t('Acompanhe os detalhes','Follow the announcement')} <span aria-hidden="true">↗</span></a></div></section>
 <section class="section about-overview"><div class="wrap about-grid"><div><p class="eyebrow">{t('O Instituto','The Institute')}</p><h2>{t('Uma instituição dedicada ao debate cibernético.','An institution dedicated to the cybersecurity debate.')}</h2>{link('institute',lang,t('Nossa identidade','About us'))}</div><div class="about-text"><p>{t('A segurança digital envolve decisões sobre pessoas, instituições e serviços essenciais. O IBDCyber contribui para essa discussão por meio de estudos, formação e interlocução com o poder público e a sociedade.','Digital security involves decisions about people, institutions and essential services. IBDCyber contributes through research, education and dialogue with public authorities and civil society.')}</p><div class="principles"><span>{t('Sem fins lucrativos','Nonprofit')}</span><span>{t('Apartidário','Nonpartisan')}</span><span>{t('Sede em Brasília','Based in Brasília')}</span></div></div></div></section>
 <section class="section practice-section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">{t('Atuação','Our work')}</p><h2>{t('Quatro frentes de trabalho.','Four areas of work.')}</h2></div><p>{t('Conheça os temas que organizam a finalidade institucional do IBDCyber.','Explore the themes that shape IBDCyber’s institutional purpose.')}</p></div><div class="practice-grid">{cards}</div></div></section>
 <section class="section front-section"><div class="wrap front-layout"><div class="front-panel"><span class="panel-label">{t('Agenda parlamentar','Parliamentary agenda')}</span><div class="front-monogram" aria-hidden="true">FP<span>CIBERSEG</span></div><p>{t('Frente Parlamentar de Apoio à Cibersegurança e à Defesa Cibernética','Frente Parlamentar de Apoio à Cibersegurança e à Defesa Cibernética')}</p><div class="panel-foot"><span>Senado Federal</span><span>{t('Resolução 55/2024','Resolution 55/2024')}</span></div></div><div class="front-copy"><p class="eyebrow">{t('Relações institucionais','Institutional relations')}</p><h2>{t('O debate técnico <br>na agenda parlamentar.','Technical debate <br>on the parliamentary agenda.')}</h2><p>{t('Conheça a FPCIBERSEG, as atividades documentadas e os vínculos comprovados com o Instituto. Cada registro preserva sua origem e o contexto de participação.','Learn about FPCIBERSEG, its documented activities and verified connections with the Institute. Each record identifies its source and the context of participation.')}</p>{button('front',lang,t('Conheça a Frente','Explore the parliamentary front'))}<div class="legislative-note"><span class="document-symbol" aria-hidden="true">↗</span><div><strong>{t('PL 4752/2025: Marco Legal da Cibersegurança','Bill 4752/2025: Cybersecurity Framework')}</strong><p>{t('Proposta em tramitação na consulta de 17/10/2026. Não é lei em vigor.','Under consideration as checked on 17 October 2026. Not enacted law.')}</p><a href="{url('knowledge')}pl4752/">{t('Consultar a proposta','Explore the proposal')} <span aria-hidden="true">→</span></a></div></div></div></div></section>
 <section class="section knowledge-section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">{t('Conhecimento','Knowledge')}</p><h2>{t('Fontes para aprofundar.','Resources for a closer look.')}</h2></div>{link('knowledge',lang,t('Acessar o acervo','Browse the collection'))}</div><div class="resource-grid">{''.join(resource(x,lang) for x in data['knowledge'][:3])}</div></div></section>
 <section class="section records-section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">{t('Agenda e registros','Events and records')}</p><h2>{t('Acompanhe a atuação.','Explore the record.')}</h2></div>{link('agenda',lang,t('Ver todos os registros','View all records'))}</div><div class="records-grid"><a class="featured-record" href="{url('agenda')}{rsa['id']}/"><div class="record-image"><img src="/assets/rsa.png" width="900" height="650" loading="lazy" alt="{t('Participação na RSA Conference, registrada na apresentação do Instituto','RSA Conference participation, documented in the Institute’s presentation')}"><span>{t('Registro institucional','Institutional record')}</span></div><div class="featured-record-text"><p class="mini-label">RSA CONFERENCE · 2025</p><h3>{t('Interlocução internacional em cibersegurança','International dialogue on cybersecurity')}</h3><span class="record-arrow" aria-hidden="true">↗</span></div></a><div class="agenda-list">{''.join(event(x,lang) for x in sorted(data['events'],key=lambda x:x['date'],reverse=True) if x['id'].startswith('front-') or x.get('featured'))}</div></div></div></section>
 </main>'''
